import itertools

n = 7
vertices = list(range(n))

# Generate edge list in lexicographic order (i,j) with i<j
edges = []
edge_index = {}
for i in range(n):
    for j in range(i+1, n):
        edge_index[(i,j)] = len(edges)
        edges.append((i,j))

print("Edge list:")
for idx, (i,j) in enumerate(edges):
    print(idx, (i,j))

# Fixed assignments assuming 0-indexed vertices
fixed = {
    3: 0,   # (0,4)
    7: 0,   # (1,3)
    12: 0,  # (2,4)
    18: 0,  # (4,5)
}

# Verify these indices correspond to edges
print("\nFixed edges (0-indexed assumption):")
for idx, val in fixed.items():
    print(idx, edges[idx], val)

# Precompute all 4-subsets and 3-subsets
subsets_4 = list(itertools.combinations(vertices, 4))
subsets_3 = list(itertools.combinations(vertices, 3))

# Precompute edge indices for each subset
red_clique_edges = []
for subset in subsets_4:
    eidx = []
    for a,b in itertools.combinations(subset, 2):
        eidx.append(edge_index[(a,b)])
    red_clique_edges.append(eidx)

blue_clique_edges = []
for subset in subsets_3:
    eidx = []
    for a,b in itertools.combinations(subset, 2):
        eidx.append(edge_index[(a,b)])
    blue_clique_edges.append(eidx)

free_vars = [i for i in range(len(edges)) if i not in fixed]
print(f"\nFree variables: {len(free_vars)}")

# Search
found = None
for mask in range(1 << len(free_vars)):
    # Build assignment
    assign = [None] * len(edges)
    for idx, val in fixed.items():
        assign[idx] = val
    for i, var in enumerate(free_vars):
        assign[var] = (mask >> i) & 1

    # Check red K4: all edges in any 4-subset must not be all 0
    ok = True
    for eidx in red_clique_edges:
        if all(assign[e] == 0 for e in eidx):
            ok = False
            break
    if not ok:
        continue

    # Check blue K3: all edges in any 3-subset must not be all 1
    for eidx in blue_clique_edges:
        if all(assign[e] == 1 for e in eidx):
            ok = False
            break
    if not ok:
        continue

    found = assign
    break

if found:
    print("\nFound solution with 0-indexed assumption:")
    print(found)
else:
    print("\nNo solution with 0-indexed assumption.")
